from decimal import Decimal
from typing import Any


def _value(record: dict, field: str) -> Any:
    value = record.get(field, "")
    return "" if value is None else value


def _text(record: dict, field: str) -> str:
    value = _value(record, field)
    return value if isinstance(value, str) else str(value)


def _number(value: Any) -> Decimal:
    if value is None or value == "":
        return Decimal(0)
    return Decimal(str(value))


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    del today
    errors: list[dict] = []

    def fail(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append({
            "code": code,
            "message": message,
            "severity": severity,
        })

    if event in ("INSERT", "UPDATE"):
        if len(_text(record, "ACCT_NM")) < 2:
            fail("E1001", "Account name too short")

        if _text(record, "ACCT_TYP") not in ("C", "P", "R", "X"):
            fail("E1002", "Invalid account type")

        if _number(_value(record, "ANN_REV")) < 0:
            fail("E1003", "Annual revenue negative")

    if event == "UPDATE":
        old_image = old or {}
        releases_hold = (
            _text(old_image, "CRED_HOLD") == "Y"
            and _text(record, "CRED_HOLD") == "N"
            and _number(_value(record, "CRED_LIMIT")) <= 0
        )
        if releases_hold:
            fail(
                "E1004",
                "Cannot release credit hold with zero credit limit",
            )

    if event in ("INSERT", "UPDATE"):
        if len(_text(record, "REGION_CD")) != 3:
            fail(
                "E1005",
                "Region code must be 3 chars",
                severity="WARN",
            )

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
